// Payload viene en $json.body (POST JSON desde AIBackHub)
const body = $input.first().json.body || $input.first().json;

// El motor envía { payload: {...} } o el contenido plano según el LLM
const payload = body.payload || body;

// Campos enviados por el motor de pruebas:
const webhookName = body.webhookName || 'desconocido';
const event = body.event || 'webhook_call';

return [{
  json: {
    ok: true,
    receivedAt: new Date().toISOString(),
    webhookName,
    event,
    summary: `n8n recibió el webhook "${webhookName}" con ${Object.keys(payload).length} campo(s) en payload.`,
    payloadEcho: payload,
    note: 'Este es un flujo de prueba. En producción aquí irían las acciones reales (Gmail, Sheets, DB, etc.) y la respuesta sería lo que el LLM verá.'
  }
}];
